def transform(grid):
    h,w=len(grid),len(grid[0])
    occupied={(r,c) for r in range(h) for c in range(w) if grid[r][c]==8}
    out=[[0]*w for _ in range(h)]
    # Candidate tiles: 2x2 squares and every 3-cell L tromino.
    tiles=[]
    for r in range(h-1):
        for c in range(w-1):
            sq={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
            if sq<=occupied: tiles.append((sq,1))
            for missing in range(4):
                cells=set(sq); cells.remove([(r,c),(r,c+1),(r+1,c),(r+1,c+1)][missing])
                if cells<=occupied:
                    color={0:2,1:4,2:3,3:5}[missing]
                    tiles.append((cells,color))
    # exact-cover recursively; prioritize covering most constrained remaining cell
    def solve(rem, chosen):
        if not rem:return chosen
        best=None; opts=None
        for p in rem:
            cand=[t for t in tiles if p in t[0] and t[0]<=rem]
            if opts is None or len(cand)<len(opts): best,opts=p,cand
            if len(cand)<=1:break
        for cells,col in opts or []:
            ans=solve(rem-cells,chosen+[(cells,col)])
            if ans is not None:return ans
        return None
    ans=solve(occupied,[])
