def transform(grid):
    h,w=len(grid),len(grid[0])
    occupied={(r,c) for r in range(h) for c in range(w) if grid[r][c]==8}
    out=[[0]*w for _ in range(h)]
    # Candidate tiles: solid 2x2 squares and 3-cell L shapes.
    tiles=[]
    for r in range(h-1):
        for c in range(w-1):
            square={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
            if square<=occupied:
                tiles.append((square,1))
            positions=[(r,c),(r,c+1),(r+1,c),(r+1,c+1)]
            # Color each L orientation according to the missing corner.
            for missing,color in enumerate((2,4,3,5)):
                cells=set(square)
                cells.remove(positions[missing])
                if cells<=occupied:
                    tiles.append((cells,color))
    # Exact-cover search: partition the occupied figure into the demonstrated tiles.
    def solve(remaining, chosen):
        if not remaining:
            return chosen
        options=None
        for cell in remaining:
            candidates=[tile for tile in tiles if cell in tile[0] and tile[0] <= remaining]
            if options is None or len(candidates)<len(options):
                options=candidates
            if len(options)==0:
                return None
        for cells,color in options or []:
            result=solve(remaining-cells,chosen+[(cells,color)])
            if result is not None:
                return result
        return None
    solution=solve(occupied,[])
    if solution is None:
        return out
    for cells,color in solution:
        for r,c in cells:
            out[r][c]=color
    return out
